import {PLANET} from './planet.js';
export function drawOrbit(canvas,o){const c=canvas.getContext('2d'),w=canvas.width,m=w/2,limit=Math.max(o.radius,Math.min(PLANET.radius+o.apoapsis,PLANET.radius*4)),scale=(m-12)/limit;c.clearRect(0,0,w,w);const circle=(r,color)=>{c.beginPath();c.arc(m,m,r*scale,0,2*Math.PI);c.fillStyle=color;c.fill();};circle(PLANET.radius+PLANET.atmosphereTop,'#3b748a');circle(PLANET.radius,'#516e63');const x=o.eccentricity>1e-6?o.evec.clone().normalize():o.r.clone().normalize(),y=o.normal.clone().cross(x).normalize();if(o.normal.lengthSq()>.5){c.beginPath();c.strokeStyle='#efb067';c.lineWidth=1.5;let pen=false;for(let i=0;i<=360;i++){const a=i*Math.PI/180,den=1+o.eccentricity*Math.cos(a),r=o.p/den;if(den<=0||r>limit*1.2){pen=false;continue;}const px=m+r*Math.cos(a)*scale,py=m-r*Math.sin(a)*scale;if(pen)c.lineTo(px,py);else c.moveTo(px,py);pen=true;}c.stroke();}const px=m+o.r.dot(x)*scale,py=m-o.r.dot(y)*scale;c.beginPath();c.arc(px,py,3,0,Math.PI*2);c.fillStyle='#fff';c.fill();}
